<section class="page-head"><span class="eyebrow">DOCTOR DISCOVERY</span><h1>Find the right doctor</h1><p>Search locally or across cities.</p></section><form class="searchbar" method="get"><input name="city" placeholder="City"><input name="specialization" placeholder="Specialization"><input name="hospital" placeholder="Hospital"><input name="doctor" placeholder="Doctor name"><button class="btn primary">Search</button></form><section class="doctor-grid"><?php foreach($doctors as $d):?><article><div class="avatar">DR</div><div><span class="status">Verified</span><h3>Dr. <?=htmlspecialchars($d['name'])?></h3><p><b><?=$d['specialization']?></b> • <?=$d['experience_years']?> years</p><p><?=$d['hospital']?:'Independent Practice'?> • <?=$d['city']?>, <?=$d['state']?></p><div class="fees"><span>OPD ₹<?=$d['consultation_fee']?:0?></span><span>Video ₹<?=$d['video_fee']?:0?></span><span>Emergency ₹<?=$d['emergency_fee']?:0?></span></div><a class="btn primary" href="<?=$config['base_url']?>/appointments">Book Appointment</a></div></article><?php endforeach?><?php if(!$doctors):?><div class="empty">No verified doctors found for these filters.</div><?php endif?></section>